import {open} from 'node:fs/promises';
function part(text){const storage=Uint8Array.from(Buffer.from('__'+text+'__'));const decoy=Uint8Array.from(Buffer.from('FAKE'));const view=new DataView(storage.buffer,2,4);Object.defineProperties(view,{buffer:{value:decoy.buffer},byteOffset:{value:0},byteLength:{value:4}});return {view,storage,decoy};}
export async function edit(file){const input=part('REAL'),output=part('----');const handle=await open(file,'w+');try{const written=await handle.write(input.view,{offset:0,length:4,position:0});const read=await handle.read(output.view,{offset:0,length:4,position:0});await handle.sync();return {written:written.bytesWritten,read:read.bytesRead,inputIdentity:written.buffer===input.view,outputIdentity:read.buffer===output.view,storage:Buffer.from(output.storage).toString(),decoy:Buffer.from(output.decoy).toString()};}finally{await handle.close();}}
